609: fn rewrite_action_items(
610:     items: Vec<ActionItem>,
611:     component: &Component,
612:     bound: &HashSet<String>,
613: ) -> Vec<ActionItem> {
614:     items
615:         .into_iter()
616:         .map(|item| match item {
617:             ActionItem::Requires(expr, span) => {
618:                 ActionItem::Requires(rewrite_expr(expr, component, bound), span)
619:             }
620:             ActionItem::Ensures(expr, span) => {
621:                 ActionItem::Ensures(rewrite_expr(expr, component, bound), span)
622:             }
623:             ActionItem::Let(name, expr, span) => {
624:                 ActionItem::Let(name, rewrite_expr(expr, component, bound), span)
625:             }
626:             ActionItem::Statement(statement) => {
627:                 ActionItem::Statement(rewrite_statement(statement, component, bound))
628:             }
629:         })
630:         .collect()
631: }
