687: fn rewrite_lvalue(lvalue: LValue, component: &Component, bound: &HashSet<String>) -> LValue {
688:     match lvalue {
689:         LValue::Var(name) => LValue::Var(rewrite_state_name(name, component)),
690:         LValue::Index(name, expr) => LValue::Index(
691:             rewrite_state_name(name, component),
692:             rewrite_expr(expr, component, bound),
693:         ),
694:         LValue::Field(base, field) => {
695:             LValue::Field(Box::new(rewrite_lvalue(*base, component, bound)), field)
696:         }
697:     }
698: }
